    },
    {
      "id": "token-and-composition-ownership",
      "kind": "design",
      "statement": "Use trigger group tokens for owned presentation, preserve genuine nested component ownership, and verify the same geometry across Fundamental and Fundamental Floating in light/dark. Keep the documented semantics and state model when composing or extending this family.",
      "sources": [
